const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
const ui={clock:document.getElementById('clock'),questTitle:document.getElementById('questTitle'),questDesc:document.getElementById('questDesc'),questFill:document.getElementById('questFill'),questCount:document.getElementById('questCount'),groveNum:document.getElementById('groveNum'),groveBar:document.getElementById('groveBar'),academyNum:document.getElementById('academyNum'),academyBar:document.getElementById('academyBar'),affinity:document.getElementById('affinity'),neighborAvatar:document.getElementById('neighborAvatar'),neighborName:document.getElementById('neighborName'),neighborRole:document.getElementById('neighborRole'),tipText:document.getElementById('tipText'),prompt:document.getElementById('prompt'),toast:document.getElementById('toast'),scrim:document.getElementById('dialogScrim'),dialogAvatar:document.getElementById('dialogAvatar'),dialogSpeaker:document.getElementById('dialogSpeaker'),dialogSub:document.getElementById('dialogSub'),dialogCopy:document.getElementById('dialogCopy'),choices:document.getElementById('choices')};
let W=0,H=0,dpr=1,camera={x:0,y:0},last=0,timer=0,toastTimer=0,dialogOpen=false,soundOn=false,audio=null;
const saved=(()=>{try{return JSON.parse(localStorage.getItem('mosslight-save')||'{}')}catch(e){return {}}})();
const state={x:saved.x||0,y:saved.y||0,day:saved.day||1,minutes:saved.minutes||494,grove:saved.grove??52,academy:saved.academy??38,affinity:saved.affinity??1,petals:saved.petals||0,quest:saved.quest||0,items:saved.items||[],met:saved.met||[],choice:saved.choice||'',spellCount:0};
const keys={};
const characters=[{id:'juniper',name:'Juniper',role:'Willow keeper',emoji:'🦊',x:-76,y:-18,color:'#d99068',accent:'#e9c78e'},{id:'rowan',name:'Rowan',role:'Apprentice stargazer',emoji:'🦉',x:107,y:-54,color:'#8793ad',accent:'#c9b276'},{id:'pip',name:'Pip',role:'Mushroom forager',emoji:'🐸',x:43,y:93,color:'#7fb28a',accent:'#e8d88f'}];
const objects=[{id:'petal1',type:'petal',x:-121,y:36,emoji:'✿',color:'#f1c4cf'},{id:'petal2',type:'petal',x:-24,y:70,emoji:'✿',color:'#e4b7cf'},{id:'petal3',type:'petal',x:24,y:-102,emoji:'✿',color:'#f2c8a9'},{id:'petal4',type:'petal',x:136,y:31,emoji:'✿',color:'#efd49e'},{id:'mushroom',type:'mushroom',x:-129,y:-56,emoji:'🍄',color:'#d99173'},{id:'well',type:'well',x:12,y:12,emoji:'✧',color:'#c6d4ad'}];
const trees=[];let seed=73731;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}for(let i=0;i<100;i++){let x=(rand()-.5)*760,y=(rand()-.5)*580;if(Math.abs(x)<185&&Math.abs(y)<155)continue;trees.push({x,y,r:15+rand()*13,h:34+rand()*30,hue:Math.floor(rand()*26),phase:rand()*7})}
const stones=[];for(let i=0;i<90;i++){let a=rand()*Math.PI*2,r=40+rand()*310;stones.push({x:Math.cos(a)*r,y:Math.sin(a)*r,size:1+rand()*3,alpha:.15+rand()*.28})}
function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize);resize();
function project(x,y,z=0){const s=Math.min(W/740,H/500,1.3);return {x:W/2+(x-y)*.72*s-camera.x,y:H/2+(x+y)*.36*s-camera.y-z*s}}
function worldScale(){return Math.min(W/740,H/500,1.3)}
function save(){try{localStorage.setItem('mosslight-save',JSON.stringify(state))}catch(e){}}
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function updateUI(){ui.groveNum.textContent=state.grove;ui.groveBar.style.width=state.grove+'%';ui.academyNum.textContent=state.academy;ui.academyBar.style.width=state.academy+'%';ui.affinity.textContent=state.affinity;ui.questFill.style.width=(Math.min(3,state.quest)/3*100)+'%';ui.questCount.textContent=Math.min(3,state.quest)+' / 3';ui.questTitle.textContent=state.quest>=3?'A lantern for the grove':state.petals?'The Lantern Seed · '+state.petals+' moonpetal'+(state.petals===1?'':'s'):'The Lantern Seed';ui.questDesc.textContent=state.quest>=3?'The old willow glows again. The commons feels a little more like home.':state.petals>=3?'Bring the moonpetals to Juniper. The old willow is ready to wake.':state.petals?`Gather ${3-state.petals} more moonpetal${state.petals===2?'':'s'}, then find Juniper.`:'Find Juniper near the old willow. A little kindness can wake the grove.';ui.clock.textContent=`Day ${state.day} · ${String(Math.floor(state.minutes/60)%12||12)}:${String(state.minutes%60).padStart(2,'0')} ${state.minutes<720?'AM':'PM'}`;let near=nearestPerson();if(near){ui.neighborAvatar.textContent=near.emoji;ui.neighborName.textContent=near.name;ui.neighborRole.textContent=near.role+' · '+(state.affinity>5?'dear friend':state.affinity>2?'getting closer':'curious')}else{ui.neighborAvatar.textContent='✦';ui.neighborName.textContent='Your neighbors';ui.neighborRole.textContent='Wander closer to say hello'}ui.prompt.classList.toggle('visible',!!near||nearestObject()!=null);ui.prompt.textContent=near?'E · Talk to '+near.name:nearestObject()?'E · Gather':'E · Interact';}
function nearestPerson(){return characters.map(c=>({...c,d:Math.hypot(c.x-state.x,c.y-state.y)})).filter(c=>c.d<42).sort((a,b)=>a.d-b.d)[0]||null}function nearestObject(){return objects.filter(o=>!state.items.includes(o.id)).map(o=>({...o,d:Math.hypot(o.x-state.x,o.y-state.y)})).filter(o=>o.d<28).sort((a,b)=>a.d-b.d)[0]||null}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function drawGround(){let grd=ctx.createLinearGradient(0,0,0,H);grd.addColorStop(0,'#a8bea0');grd.addColorStop(.52,'#829b78');grd.addColorStop(1,'#6d8267');ctx.fillStyle=grd;ctx.fillRect(0,0,W,H);const s=worldScale();let p=project(0,0);ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ctx.fillStyle='#77916d';ctx.beginPath();ctx.ellipse(0,0,355,260,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#a1ae7c55';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,325,238,0,0,Math.PI*2);ctx.stroke();
// winding pale path
ctx.beginPath();ctx.moveTo(-350,178);ctx.bezierCurveTo(-230,140,-205,185,-118,110);ctx.bezierCurveTo(-48,52,-71,45,0,7);ctx.bezierCurveTo(93,-40,81,-115,166,-119);ctx.bezierCurveTo(245,-129,268,-167,337,-193);ctx.strokeStyle='#c9c39c';ctx.lineWidth=40;ctx.lineCap='round';ctx.stroke();ctx.beginPath();ctx.moveTo(-350,178);ctx.bezierCurveTo(-230,140,-205,185,-118,110);ctx.bezierCurveTo(-48,52,-71,45,0,7);ctx.bezierCurveTo(93,-40,81,-115,166,-119);ctx.bezierCurveTo(245,-129,268,-167,337,-193);ctx.strokeStyle='#d9d0aa';ctx.lineWidth=32;ctx.stroke();
for(const st of stones){ctx.globalAlpha=st.alpha;ctx.fillStyle='#e2d6ae';ctx.beginPath();ctx.ellipse(st.x,st.y,st.size*1.6,st.size,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// little grass flecks
for(let i=0;i<180;i++){let x=((i*97)%680)-340,y=((i*157)%480)-240;ctx.strokeStyle=i%3?'#d4d7a833':'#f0e2b344';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+2,y-4);ctx.stroke()}
ctx.restore()}
function drawPathObject(x,y,label,sub){const p=project(x,y);ctx.save();ctx.textAlign='center';ctx.font=`600 ${Math.max(9,10*worldScale())}px DM Sans`;ctx.fillStyle='#f0ead4';ctx.shadowColor='#26362d';ctx.shadowBlur=5;ctx.fillText(label,p.x,p.y);ctx.shadowBlur=0;if(sub){ctx.font=`${Math.max(8,8*worldScale())}px DM Sans`;ctx.fillStyle='#e1ddc6';ctx.fillText(sub,p.x,p.y+12)}ctx.restore()}
function drawCottage(x,y){const p=project(x,y),s=worldScale();ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ellipse(0,4,62,20,'#263a2d44');ctx.fillStyle='#c5aa7d';ctx.fillRect(-43,-47,86,52);ctx.beginPath();ctx.moveTo(-52,-43);ctx.lineTo(0,-83);ctx.lineTo(52,-43);ctx.closePath();ctx.fillStyle='#754d43';ctx.fill();ctx.strokeStyle='#d8bc86';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#31453b';ctx.fillRect(-10,-27,20,32);ellipse(0,-28,3,3,'#e1c47f');ctx.fillStyle='#d0c493';ctx.fillRect(-34,-34,13,13);ctx.fillRect(21,-34,13,13);ctx.strokeStyle='#f0d99b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-27.5,-34);ctx.lineTo(-27.5,-21);ctx.moveTo(21,-27.5);ctx.lineTo(34,-27.5);ctx.stroke();ctx.restore()}
function drawAcademy(x,y){const p=project(x,y),s=worldScale();ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ellipse(0,7,82,24,'#24392c44');ctx.fillStyle='#8c9275';ctx.fillRect(-59,-51,118,57);ctx.beginPath();ctx.moveTo(-68,-50);ctx.lineTo(-42,-79);ctx.lineTo(-15,-50);ctx.lineTo(10,-84);ctx.lineTo(38,-50);ctx.lineTo(65,-75);ctx.lineTo(67,-45);ctx.closePath();ctx.fillStyle='#52665a';ctx.fill();ctx.fillStyle='#c3b38a';for(let i=-2;i<=2;i++){ctx.beginPath();ctx.arc(i*22,-31,5,Math.PI,0);ctx.fill();ctx.fillRect(i*22-5,-31,10,12)}ctx.fillStyle='#413d35';ctx.fillRect(-7,-22,14,28);ctx.strokeStyle='#d9c985';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-72);ctx.lineTo(0,-88);ctx.stroke();ctx.beginPath();ctx.arc(0,-90,4,0,7);ctx.fillStyle='#f3da90';ctx.fill();ctx.restore()}
function drawTree(t,tm){const p=project(t.x,t.y),s=worldScale(),sway=Math.sin(tm*.001+t.phase)*1.5;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ellipse(0,4,t.r*1.15,t.r*.48,'#233a2b3d');ctx.fillStyle='#695443';ctx.fillRect(-4,-t.h*.55,8,t.h*.58);ctx.strokeStyle='#82664b';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,-t.h*.45);ctx.lineTo(-10,-t.h*.76);ctx.moveTo(2,-t.h*.5);ctx.lineTo(12,-t.h*.77);ctx.stroke();const base=['#476e51','#527956','#64865b','#6d875c'][t.hue%4];ellipse(-9+sway,-t.h*.65,t.r*.85,t.r*.94,base);ellipse(9+sway,-t.h*.77,t.r*.84,t.r*.96,['#537858','#618459','#718960'][t.hue%3]);ellipse(-1+sway,-t.h*1.02,t.r*.79,t.r*.84,['#68875a','#799268','#64845e'][t.hue%3]);ellipse(-8+sway-4,-t.h*.69,t.r*.3,t.r*.24,'#a3ae7755');ctx.restore()}
function drawCharacter(c,tm){const p=project(c.x,c.y),s=worldScale(),isPlayer=c.id==='player',bob=Math.sin(tm*.006+(isPlayer?0:c.x))*(isPlayer?1.5:2);ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ellipse(0,3,12,6,'#23372d55');if(isPlayer){ctx.fillStyle='#dfca91';ctx.beginPath();ctx.ellipse(0,-12+bob,8,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#495f55';ctx.beginPath();ctx.moveTo(-8,-15+bob);ctx.lineTo(-7,-23+bob);ctx.lineTo(7,-23+bob);ctx.lineTo(8,-15+bob);ctx.fill();ctx.fillStyle='#e7d8ac';ctx.beginPath();ctx.arc(0,-27+bob,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#5e754f';ctx.beginPath();ctx.moveTo(-8,-29+bob);ctx.quadraticCurveTo(0,-38+bob,10,-29+bob);ctx.closePath();ctx.fill()}else{ctx.fillStyle=c.color;ctx.beginPath();ctx.ellipse(0,-13+bob,9,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=c.accent;ctx.beginPath();ctx.arc(0,-28+bob,8,0,Math.PI*2);ctx.fill();ctx.fillStyle=c.color;ctx.beginPath();ctx.moveTo(-6,-32+bob);ctx.lineTo(-9,-42+bob);ctx.lineTo(-1,-36+bob);ctx.moveTo(5,-33+bob);ctx.lineTo(11,-41+bob);ctx.lineTo(8,-32+bob);ctx.fill();ctx.fillStyle='#29352c';ctx.beginPath();ctx.arc(-3,-28+bob,1.1,0,7);ctx.arc(3,-28+bob,1.1,0,7);ctx.fill();ctx.fillStyle=c.accent;ctx.fillRect(-6,-4,12,3);if(c.id==='rowan'){ctx.fillStyle='#efcf81';ctx.beginPath();ctx.arc(0,-45+bob,3,0,7);ctx.fill()}}ctx.restore()}
function drawObjects(tm){for(const o of objects){if(state.items.includes(o.id))continue;const p=project(o.x,o.y),s=worldScale(),pulse=1+Math.sin(tm*.004+o.x)*.1;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ellipse(0,2,9,4,'#23362c44');ctx.font=`${o.type==='well'?17:18}px serif`;ctx.textAlign='center';ctx.fillStyle=o.color;ctx.shadowColor=o.color;ctx.shadowBlur=o.type==='well'?14:8;ctx.fillText(o.emoji,0,-6*pulse);ctx.shadowBlur=0;ctx.restore()}}
function drawMagic(tm){const p=project(-76,-18,-12);ctx.save();ctx.globalAlpha=.35+Math.sin(tm*.004)*.14;ctx.strokeStyle='#e6d68d';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(p.x,p.y,25+Math.sin(tm*.003)*3,0,7);ctx.stroke();ctx.restore();for(let i=0;i<15;i++){let x=Math.sin(tm*.0004+i*4)*10,y=Math.cos(tm*.0007+i*2)*8;const q=project(-76+x,-18+y,-27-i%3*3);ctx.globalAlpha=.3+((i%5)/8);ctx.fillStyle='#fff0b6';ctx.fillRect(q.x,q.y,2,2)}ctx.globalAlpha=1}

function render(tm){if(!W||!H)return;ctx.setTransform(dpr,0,0,dpr,0,0);drawGround();const drawables=[...trees.map(t=>({y:t.x+t.y,draw:()=>drawTree(t,tm)})),{y:-211,draw:()=>drawAcademy(230,-190)},{y:143,draw:()=>drawCottage(-177,138)},{y:0,draw:()=>drawMagic(tm)},...objects.map(o=>({y:o.x+o.y+1,draw:()=>{}})),...characters.map(c=>({y:c.x+c.y,draw:()=>drawCharacter(c,tm)})),{y:state.x+state.y,draw:()=>drawCharacter({id:'player'},tm)}];drawables.sort((a,b)=>a.y-b.y);for(const d of drawables)d.draw();drawObjects(tm);drawPathObject(230,-190,'STARFALL ACADEMY','classes · stargazing · magic');drawPathObject(-177,138,'THE LITTLE COMMONS','Juniper’s willow house');if(state.quest>=3){const p=project(-76,-18,-30);ctx.save();ctx.globalAlpha=.6+Math.sin(tm*.004)*.18;ctx.fillStyle='#ffe59b';ctx.shadowColor='#ffe59b';ctx.shadowBlur=22;ctx.beginPath();ctx.arc(p.x,p.y-6,9,0,Math.PI*2);ctx.fill();ctx.restore()}const target=nearestPerson();if(target){const p=project(target.x,target.y,-54);ctx.save();ctx.fillStyle='#f6e5ad';ctx.textAlign='center';ctx.font=`${13*worldScale()}px serif`;ctx.fillText('✦',p.x,p.y+Math.sin(tm*.004)*3);ctx.restore()}}
function move(dt){if(dialogOpen)return;let dx=0,dy=0;if(keys.KeyW||keys.ArrowUp||keys.up)dy-=1;if(keys.KeyS||keys.ArrowDown||keys.down)dy+=1;if(keys.KeyA||keys.ArrowLeft||keys.left)dx-=1;if(keys.KeyD||keys.ArrowRight||keys.right)dx+=1;if(dx||dy){let n=Math.hypot(dx,dy);state.x+=dx/n*dt*.12;state.y+=dy/n*dt*.12;state.x=Math.max(-345,Math.min(345,state.x));state.y=Math.max(-255,Math.min(255,state.y));state.minutes+=dt*.0032;if(state.minutes>=1440){state.minutes-=1440;state.day++}save()}const s=worldScale();camera.x+=(state.x-state.y)*.72*s*.72-camera.x*.72;camera.y+=(state.x+state.y)*.36*s*.72-camera.y*.72;updateUI()}
function frame(tm){let dt=Math.min(40,tm-(last||tm));last=tm;move(dt);render(tm);requestAnimationFrame(frame)}requestAnimationFrame(frame);
function openDialog(person){dialogOpen=true;ui.scrim.classList.add('open');let c=person||{id:'grove',name:'The old well',role:'A quiet place to listen',emoji:'✧'};ui.dialogAvatar.textContent=c.emoji;ui.dialogSpeaker.textContent=c.name;ui.dialogSub.textContent=c.role;const opts=[];if(c.id==='juniper'){ui.dialogCopy.textContent=state.quest>=3?'The lantern seed glows softly beneath the willow. You gave this little corner of the world a lovely beginning.':state.petals>=3?'Three moonpetals! You really listened to the grove. Shall we wake the lantern seed together?':'The old willow hasn’t glowed in years. I think it misses being part of something. Moonpetals might help… but first, what brings you to our little commons?';if(state.quest>=3){opts.push(['Tell me a story about this place.','The lantern seed was my grandmother’s. She said it shines brightest when shared.']);opts.push(['Would you like to walk together?','I would like that very much.']);}else if(state.petals>=3){opts.push(['Offer the moonpetals and wake the seed','quest']);opts.push(['Keep the petals for now','I understand. The choice is yours, always.']);}else{opts.push(['I’d love to help the willow bloom.','kind']);opts.push(['I’m just exploring. What should I see?','explore']);opts.push(['The grove is beautiful. Thank you for keeping it.','compliment']);}}else if(c.id==='rowan'){ui.dialogCopy.textContent='I came to Starfall to study the constellations, but the best discoveries happen when I put the books down. What do you think magic is for?';opts.push(['For helping people and places grow.','kind']);opts.push(['For discovering what no one has seen.','explore']);opts.push(['Can you teach me a little spell?','spell']);}else if(c.id==='pip'){ui.dialogCopy.textContent='Oh, hello! I’m Pip. These mushrooms only sing after rain. I’m collecting their little songs for the village festival. Want to lend a hand?';opts.push(['I’ll gather some with you.','kind']);opts.push(['Tell me your favorite thing about the grove.','compliment']);opts.push(['What’s that glowing one?','explore']);}else{ui.dialogCopy.textContent='The water ripples though there is no wind. A soft warmth stirs below the stone. What will you leave here?';opts.push(['A moonpetal, for the grove','kind']);opts.push(['A quiet wish for a new beginning','wish']);opts.push(['Listen for a moment','listen']);}ui.choices.replaceChildren();for(const [label,result] of opts){const b=document.createElement('button');b.className='choice';b.innerHTML=`<span>${label}</span><small>${result==='quest'?'Wake the lantern seed':result==='kind'?'+ friendship · + grove kin':result==='explore'?'+ curiosity':result==='compliment'?'+ friendship':result==='spell'?'Learn a small spell':'Choose your path'}</small>`;b.onclick=()=>choose(c,result);ui.choices.appendChild(b)}setTimeout(()=>ui.choices.querySelector('button')?.focus(),20)}
function closeDialog(){dialogOpen=false;ui.scrim.classList.remove('open')}
function choose(c,result){closeDialog();if(result==='quest'){state.quest=3;state.grove=Math.min(100,state.grove+17);state.affinity++;ui.tipText.textContent='The lantern seed remembers your kindness. Perhaps visit Starfall Academy next — Rowan has been waiting to show someone the stars.';toast('The Lantern Seed is awake ✨');}else if(result==='kind'){state.affinity++;state.grove=Math.min(100,state.grove+6);state.choice='kind';if(c.id==='juniper'){ui.tipText.textContent='Juniper trusts you with the willow’s secret. Moonpetals glimmer along the paths of Brackenroot Commons.';toast('Juniper’s friendship grew ♥')}else if(c.id==='rowan'){state.academy=Math.min(100,state.academy+7);ui.tipText.textContent='Rowan smiles. Starfall Academy feels a little less mysterious now.';toast('Rowan feels seen ♥')}else{ui.tipText.textContent='Pip shows you where the sweetest mushrooms grow.';toast('Pip is glad to have a friend ♥')}}else if(result==='explore'){state.choice='explore';if(c.id==='juniper'){state.grove=Math.max(0,state.grove-2);ui.tipText.textContent='Juniper points you down a winding path. Sometimes the best answer is to go see for yourself.';toast('A new path is waiting.')}else{state.academy=Math.min(100,state.academy+5);ui.tipText.textContent='Curiosity draws you closer to Starfall Academy. Rowan loves a question.';toast('Your curiosity is noticed ✦')}}else if(result==='compliment'){state.affinity++;state.grove=Math.min(100,state.grove+4);ui.tipText.textContent='A warm feeling settles over the commons. You notice a moonpetal sparkling nearby.';toast('That meant more than you know ♥')}else if(result==='spell'){state.academy=Math.min(100,state.academy+6);state.spellCount++;ui.tipText.textContent='Rowan teaches you a little star-spark. Press ✧ or Space to practice it.';toast('Star-spark learned ✨')}else if(result==='wish'||result==='listen'){state.grove=Math.min(100,state.grove+3);toast(result==='wish'?'Your wish joins the water.':'The grove seems to breathe with you.')}save();updateUI()}
function interact(){if(dialogOpen){closeDialog();return}const person=nearestPerson();if(person){openDialog(person);return}const obj=nearestObject();if(obj){if(obj.type==='petal'){state.items.push(obj.id);state.petals++;state.quest=Math.max(state.quest,Math.min(2,state.petals));state.grove=Math.min(100,state.grove+2);toast('Moonpetal gathered ✿');ui.tipText.textContent=state.petals>=3?'You have enough moonpetals. Take them to Juniper by the old willow.':'Moonpetals collected: '+state.petals+' / 3. Their soft glow points the way.'}else if(obj.type==='mushroom'){state.items.push(obj.id);state.grove=Math.min(100,state.grove+2);toast('Singing mushroom collected ♪');ui.tipText.textContent='A tiny tune hums in your pocket. Pip might enjoy hearing it.'}else{openDialog(null);return}save();updateUI();return}toast('Wander a little closer to someone or something ✦')}
function castSpell(){state.spellCount++;const p=project(state.x,state.y,-20);for(let i=0;i<8;i++){const a=i*Math.PI/4;ctx.fillStyle='#f8eab2';ctx.shadowColor='#ffe18a';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(p.x+Math.cos(a)*20,p.y+Math.sin(a)*16,2+Math.random()*2,0,7);ctx.fill()}ctx.shadowBlur=0;state.grove=Math.min(100,state.grove+1);if(state.spellCount===1)toast('A little star-spark! ✧');else toast('Magic loves a gentle hand ✨');save();updateUI()}
