function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize);resize();
function project(x,y,z=0){const s=Math.min(W/740,H/500,1.3);return {x:W/2+(x-y)*.72*s-camera.x,y:H/2+(x+y)*.36*s-camera.y-z*s}}
function worldScale(){return Math.min(W/740,H/500,1.3)}function save(){try{localStorage.setItem('mosslight-save',JSON.stringify(state))}catch(e){}}
